"""Complete final verification."""
import time
time.sleep(20)

from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

def connect(dt, host, user, pw):
    return ConnectHandler(device_type=dt, host=host, username=user, password=pw)

print("=" * 60)
print("1. ADJACENCIES AND SESSIONS")
print("=" * 60)

# HQ-Edge
conn = connect("vyos", "192.168.122.11", "vyos", "test")
out = conn.send_command("show bgp summary", read_timeout=15)
for line in out.splitlines():
    if "203.0.113" in line:
        parts = line.split()
        print(f"  BGP {parts[0]}: AS {parts[2]}, State/PfxRcvd={parts[9]}, PfxSnt={parts[10]}")
out = conn.send_command("show ip ospf neighbor", read_timeout=15)
for line in out.splitlines():
    if "Full" in line:
        parts = line.split()
        print(f"  OSPF HQ-Edge <-> {parts[0]}: {parts[2]} on {parts[6]}")
conn.disconnect()

# Hub-A
conn = connect("vyos", "192.168.122.12", "vyos", "test")
out = conn.send_command("show ip ospf neighbor", read_timeout=15)
for line in out.splitlines():
    if "Full" in line:
        parts = line.split()
        print(f"  OSPF Hub-A <-> {parts[0]}: {parts[2]} on {parts[6]}")
conn.disconnect()

# Hub-B
conn = connect("vyos", "192.168.122.13", "vyos", "test")
out = conn.send_command("show ip ospf neighbor", read_timeout=15)
for line in out.splitlines():
    if "Full" in line:
        parts = line.split()
        print(f"  OSPF Hub-B <-> {parts[0]}: {parts[2]} on {parts[6]}")
conn.disconnect()

print("\n" + "=" * 60)
print("2. ROUTING TABLES")
print("=" * 60)

# HQ-Edge BGP
conn = connect("vyos", "192.168.122.11", "vyos", "test")
out = conn.send_command("show bgp ipv4 unicast", read_timeout=15)
print("\nHQ-Edge BGP table:")
for line in out.splitlines():
    if "*" in line and "Network" not in line:
        print(f"  {line.strip()}")
out = conn.send_command("show ip route ospf", read_timeout=15)
print("\nHQ-Edge OSPF routes:")
for line in out.splitlines():
    if "O>" in line:
        print(f"  {line.strip()}")
conn.disconnect()

# Hub-A default
conn = connect("vyos", "192.168.122.12", "vyos", "test")
out = conn.send_command("show ip route 0.0.0.0/0", read_timeout=15)
print("\nHub-A default route:")
for line in out.splitlines():
    if "O>" in line or "via" in line:
        print(f"  {line.strip()}")
conn.disconnect()

# Hub-B default
conn = connect("vyos", "192.168.122.13", "vyos", "test")
out = conn.send_command("show ip route 0.0.0.0/0", read_timeout=15)
print("\nHub-B default route:")
for line in out.splitlines():
    if "O>" in line or "via" in line:
        print(f"  {line.strip()}")
conn.disconnect()

# Branch-4 routes (totally stubby)
conn = connect("mikrotik_routeros", "192.168.122.24", "admin", "test")
out = conn.send_command("/ip route print terse", read_timeout=15)
print("\nBranch-4 routes:")
for line in out.splitlines():
    if line.strip():
        print(f"  {line.strip()}")
conn.disconnect()

# Branch-1 routes (check summarization)
conn = connect("mikrotik_routeros", "192.168.122.21", "admin", "test")
out = conn.send_command("/ip route print terse", read_timeout=15)
print("\nBranch-1 routes (10.x entries):")
for line in out.splitlines():
    if "10." in line and "192.168" not in line:
        print(f"  {line.strip()}")
conn.disconnect()

print("\n" + "=" * 60)
print("3. HOST REACHABILITY")
print("=" * 60)

non_guest = {
    "B1-PC1": ("192.168.122.31", "10.1.1.10"),
    "B1-PC2": ("192.168.122.32", "10.1.1.11"),
    "B2-PC1": ("192.168.122.33", "10.1.2.10"),
    "B2-PC2": ("192.168.122.34", "10.1.2.11"),
    "B3-PC1": ("192.168.122.35", "10.1.3.10"),
    "B3-PC2": ("192.168.122.36", "10.1.3.11"),
    "B4-PC1": ("192.168.122.37", "10.2.1.10"),
    "B4-PC2": ("192.168.122.38", "10.2.1.11"),
}
guest = {
    "B4-PC3": ("192.168.122.39", "10.2.2.10"),
    "B4-PC4": ("192.168.122.40", "10.2.2.11"),
}
all_hosts = {**non_guest, **guest}

def ping_from(src_name, src_mgmt, targets):
    res = {}
    try:
        conn = connect("linux", src_mgmt, "root", "alpine")
        for tgt_name, tgt_ip in targets:
            out = conn.send_command(f"ping -c 2 -W 3 {tgt_ip}", read_timeout=15)
            success = " 0% packet loss" in out
            res[(src_name, tgt_name)] = success
        conn.disconnect()
    except Exception as e:
        for tgt_name, tgt_ip in targets:
            res[(src_name, tgt_name)] = f"ERROR: {e}"
    return res

tasks = []
for src_name, (src_mgmt, _) in all_hosts.items():
    targets = []
    for tgt_name, (_, tgt_ip) in all_hosts.items():
        if src_name != tgt_name:
            targets.append((tgt_name, tgt_ip))
    targets.append(("8.8.8.8", "8.8.8.8"))
    targets.append(("1.1.1.1", "1.1.1.1"))
    tasks.append((src_name, src_mgmt, targets))

results = {}
with ThreadPoolExecutor(max_workers=10) as pool:
    futures = [pool.submit(ping_from, s, m, t) for s, m, t in tasks]
    for f in as_completed(futures):
        results.update(f.result())

ng = sorted(non_guest.keys())
g = sorted(guest.keys())

